package api.publica;

import java.sql.*;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.*;
import api.publica.ConvocatoriaPublicaDTO.*;
import config.ConexionBD;
import negocio.PosicionJugador;

public class ConsultaConvocatoriasComunidadService {
 public static final int TAMANO_PREDETERMINADO=12,TAMANO_MAXIMO=48;
 public record Filtros(LocalDate fecha,Long categoriaId,PosicionJugador posicion,Integer lugares){public Filtros{if(categoriaId!=null&&categoriaId<=0)throw new IllegalArgumentException("La categoria debe ser un ID positivo.");if(lugares!=null&&(lugares<1||lugares>3))throw new IllegalArgumentException("Los lugares deben estar entre 1 y 3.");}public static Filtros vacios(){return new Filtros(null,null,null,null);}}
 @FunctionalInterface interface ProveedorConexion{Connection obtener()throws SQLException;}
 @FunctionalInterface interface ProveedorFecha{LocalDateTime ahora();}
 private final ProveedorConexion conexiones;private final ProveedorFecha reloj;
 public ConsultaConvocatoriasComunidadService(){this(ConexionBD::obtenerConexion,LocalDateTime::now);}
 ConsultaConvocatoriasComunidadService(ProveedorConexion c,ProveedorFecha r){if(c==null||r==null)throw new IllegalArgumentException("Las dependencias son obligatorias.");conexiones=c;reloj=r;}
 public Pagina listar(Filtros filtros,int pagina,int tamano){validarPaginacion(pagina,tamano);Filtros f=filtros==null?Filtros.vacios():filtros;int offset=Math.multiplyExact(pagina-1,tamano);Consulta q=construir(f,reloj.ahora());try(Connection c=conexiones.obtener()){long total=contar(c,q);List<Turno> items=total==0?List.of():consultar(c,q,tamano,offset);int paginas=total==0?0:(int)Math.ceil((double)total/tamano);return new Pagina(items,pagina,tamano,total,paginas);}catch(SQLException e){throw new RuntimeException("No se pudo consultar el catalogo publico de turnos abiertos.",e);}}
 static void validarPaginacion(int p,int t){if(p<1)throw new IllegalArgumentException("La pagina debe ser mayor o igual a 1.");if(t<1||t>TAMANO_MAXIMO)throw new IllegalArgumentException("El tamano debe estar entre 1 y "+TAMANO_MAXIMO+".");}
 static LocalDate fecha(String v){if(v==null||v.isBlank())return null;try{return LocalDate.parse(v.trim());}catch(RuntimeException e){throw new IllegalArgumentException("La fecha debe usar el formato AAAA-MM-DD.");}}
 static Integer lugares(String v){if(v==null||v.isBlank())return null;try{int n=Integer.parseInt(v.trim());if(n<1||n>3)throw new NumberFormatException();return n;}catch(RuntimeException e){throw new IllegalArgumentException("Los lugares deben estar entre 1 y 3.");}}
 static PosicionJugador posicion(String v){if(v==null||v.isBlank())return null;try{return PosicionJugador.valueOf(v.trim().toUpperCase(Locale.ROOT));}catch(RuntimeException e){throw new IllegalArgumentException("La posicion debe ser DRIVE o REVES.");}}
 private long contar(Connection c,Consulta q)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT COUNT(*) "+q.sql)){bind(s,q.params,1);try(ResultSet r=s.executeQuery()){r.next();return r.getLong(1);}}}
 private List<Turno> consultar(Connection c,Consulta q,int limite,int offset)throws SQLException{String select="SELECT cv.id convocatoria_id,r.id reserva_id,r.fecha,r.hora_inicio,r.hora_fin,ca.nombre cancha,cv.participantes_confirmados,cv.lugares_buscados,cv.categoria_deportiva_id categoria_buscada_id,cb.nombre categoria_buscada_nombre,cb.color_hex categoria_buscada_color,cv.posicion_buscada,cv.comentario,p.id perfil_id,p.nombre_publico,p.posicion_preferida,cc.id categoria_convocante_id,cc.nombre categoria_convocante_nombre,cc.color_hex categoria_convocante_color ";try(PreparedStatement s=c.prepareStatement(select+q.sql+" ORDER BY r.fecha,r.hora_inicio,cv.id LIMIT ? OFFSET ?")){int i=bind(s,q.params,1);s.setInt(i++,limite);s.setInt(i,offset);try(ResultSet r=s.executeQuery()){List<Turno> out=new ArrayList<>();while(r.next())out.add(map(r));return List.copyOf(out);}}}
 static Consulta construir(Filtros f,LocalDateTime ahora){StringBuilder q=new StringBuilder(base());List<Object> p=new ArrayList<>();q.append(" AND TIMESTAMP(r.fecha,r.hora_inicio)>?");p.add(ahora);if(f.fecha()!=null){q.append(" AND r.fecha=?");p.add(f.fecha());}if(f.categoriaId()!=null){q.append(" AND cv.categoria_deportiva_id=?");p.add(f.categoriaId());}if(f.posicion()!=null){q.append(" AND cv.posicion_buscada=?");p.add(f.posicion().name());}if(f.lugares()!=null){q.append(" AND cv.lugares_buscados=?");p.add(f.lugares());}return new Consulta(q.toString(),List.copyOf(p));}
 static String base(){return "FROM comunidad_convocatorias cv JOIN reservas r ON r.id=cv.reserva_id JOIN canchas ca ON ca.id=r.cancha_id JOIN perfiles_jugador p ON p.id=cv.perfil_creador_id AND p.activo=TRUE LEFT JOIN categorias_deportivas cb ON cb.id=cv.categoria_deportiva_id AND cb.activo=TRUE LEFT JOIN jugador_categorias jc ON jc.perfil_jugador_id=p.id AND jc.estado='VIGENTE' LEFT JOIN categorias_deportivas cc ON cc.id=jc.categoria_deportiva_id AND cc.activo=TRUE WHERE cv.estado IN ('ABIERTA','EN_COORDINACION') AND cv.clave_activa=1 AND cv.fecha_expiracion>? AND r.estado IN ('PENDIENTE','CONFIRMADA')";}
 private int bind(PreparedStatement s,List<Object> vs,int i)throws SQLException{for(Object v:vs){if(v instanceof LocalDateTime x)s.setTimestamp(i++,Timestamp.valueOf(x));else if(v instanceof LocalDate x)s.setDate(i++,java.sql.Date.valueOf(x));else if(v instanceof Long x)s.setLong(i++,x);else if(v instanceof Integer x)s.setInt(i++,x);else s.setString(i++,v.toString());}return i;}
 private Turno map(ResultSet r)throws SQLException{Categoria buscada=categoria(r,"categoria_buscada_id","categoria_buscada_nombre","categoria_buscada_color");Categoria actual=categoria(r,"categoria_convocante_id","categoria_convocante_nombre","categoria_convocante_color");String nombre=ConsultaJugadoresComunidadService.limpiarNombre(r.getString("nombre_publico"));int confirmados=r.getInt("participantes_confirmados"),buscados=r.getInt("lugares_buscados"),disponibles=Math.max(0,Math.min(buscados,4-confirmados));Convocante convocante=new Convocante(r.getLong("perfil_id"),nombre,ConsultaJugadoresComunidadService.iniciales(nombre),r.getString("posicion_preferida"),actual);return new Turno(r.getLong("convocatoria_id"),r.getLong("reserva_id"),r.getDate("fecha").toLocalDate(),r.getTime("hora_inicio").toLocalTime(),r.getTime("hora_fin").toLocalTime(),r.getString("cancha"),confirmados,buscados,disponibles,confirmados+" de 4, falta "+disponibles+(disponibles==1?" jugador":" jugadores"),buscada,r.getString("posicion_buscada"),r.getString("comentario"),convocante);}
 private Categoria categoria(ResultSet r,String id,String nombre,String color)throws SQLException{long x=r.getLong(id);return r.wasNull()?null:new Categoria(x,r.getString(nombre),r.getString(color));}
 record Consulta(String sql,List<Object> params){}
}
